import functools
import random
import time


def retry(max_attempts=3, base_delay=1.0, max_delay=30.0, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            delay = base_delay
            while True:
                attempt += 1
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt >= max_attempts:
                        raise
                    sleep_for = min(delay, max_delay)
                    time.sleep(sleep_for + random.uniform(0, sleep_for * 0.1))
                    delay *= 2
        return wrapper
    return decorator


@retry(max_attempts=5, base_delay=0.5, exceptions=(ConnectionError,))
def fetch(url):
    ...
```

Usage: apply `@retry(...)` above a function; it re-runs the call up to `max_attempts` times, doubling the wait (capped at `max_delay`, with small jitter) between failures, then re-raises the last exception.
